/** Proposed source-data, actual controller/item/kinetic/native target regressions. STAGED, UNRUN. */
public class FlapDisplayGameTests {
    private static final BlockPos P=new BlockPos(4,5,4);
    private static BlockState state(){return AllBlocks.DISPLAY_BOARD.defaultBlockState().setValue(FlapDisplayBlock.HORIZONTAL_FACING,Direction.SOUTH);}
    private static FlapDisplayBlockEntity be(GameTestHelper h,BlockPos pos){return h.getBlockEntity(pos,FlapDisplayBlockEntity.class);}
    private static void board(GameTestHelper h){h.setBlock(P,state());be(h,P).updateControllerStatus();}
    private static void rectangle(GameTestHelper h,int width,int height){for(int y=0;y<height;y++)for(int x=0;x<width;x++)h.setBlock(P.east(x).below(y),state());}
    private static void power(GameTestHelper h,int rpm){if(!h.getBlockState(P).is(AllBlocks.DISPLAY_BOARD))board(h);h.setBlock(P.west(),AllBlocks.COGWHEEL.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));h.setBlock(P.west().north(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.SOUTH));h.getBlockEntity(P.west().north(),KineticBlockEntity.class).setGeneratedSpeed(rpm);}
    private static Player user(GameTestHelper h,ItemStack item){var user=h.makeMockPlayer(GameType.SURVIVAL);user.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,2));user.setItemInHand(InteractionHand.MAIN_HAND,item);return user;}
    private static ItemStack tag(String text){var stack=new ItemStack(Items.NAME_TAG);stack.set(DataComponents.CUSTOM_NAME,Component.literal(text));return stack;}
    private static InteractionResult use(GameTestHelper h,Player user,int line){var pos=h.absolutePos(P);var hit=new BlockHitResult(new Vec3(pos.getX()+.5,pos.getY()+.75-line*.5,pos.getZ()+13/16d),Direction.SOUTH,pos,false);return user.getMainHandItem().isEmpty()?h.getBlockState(P).useWithoutItem(h.getLevel(),user,hit):h.getBlockState(P).useItemOn(user.getMainHandItem(),h.getLevel(),user,InteractionHand.MAIN_HAND,hit);}
    private static String text(GameTestHelper h,int line){var component=be(h,P).getLines().get(line).getSections().getFirst().getText();return component==null?"":component.getString();}
    private static TagValueOutput output(GameTestHelper h){return TagValueOutput.createWithContext(ProblemReporter.DISCARDING,h.getLevel().registryAccess());}
    private static ValueInput input(GameTestHelper h,CompoundTag tag){return TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),tag);}

    @GameTest public void actualBoardHasItsOwnRegisteredTypeZeroStressAndCogWithoutShaftFaces(GameTestHelper h){board(h);h.assertTrue(be(h,P).getType()==AllBlockEntityTypes.FLAP_DISPLAY&&AllBlocks.DISPLAY_BOARD.asItem()!=Items.AIR&&BlockStressValues.getImpact(AllBlocks.DISPLAY_BOARD)==0,"Real source board/type/item and no-impact stress registration");for(var side:Direction.values())h.assertFalse(AllBlocks.DISPLAY_BOARD.hasShaftTowards(h.getLevel(),h.absolutePos(P),state(),side),"Source board has no fictitious shaft port");h.assertValueEqual(AllBlocks.DISPLAY_BOARD.getRotationAxis(state()),Direction.Axis.Z,"Cog axis follows source facing");h.succeed();}
    @GameTest public void actualBoardShapesKeepTheSourceTenVoxelDepthForEveryFacing(GameTestHelper h){for(var face:Direction.Plane.HORIZONTAL){var state=state().setValue(FlapDisplayBlock.HORIZONTAL_FACING,face);var shape=state.getShape(h.getLevel(),h.absolutePos(P)).bounds();h.assertTrue(shape.getYsize()==1&&(face.getAxis()==Direction.Axis.X?shape.getXsize():shape.getZsize())==10/16d,"Native source shape for "+face);}h.succeed();}
    @GameTest public void realBlockItemPlacementCopiesBoardFacingAndPaysOneSurvivalItem(GameTestHelper h){board(h);var stack=new ItemStack(AllBlocks.DISPLAY_BOARD,2);var user=user(h,stack);var support=h.absolutePos(P);var context=new BlockPlaceContext(new UseOnContext(user,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(.5,0,0),Direction.EAST,support,false)));h.assertTrue(((BlockItem)stack.getItem()).place(context).consumesAction()&&h.getBlockState(P.east()).getValue(FlapDisplayBlock.HORIZONTAL_FACING)==Direction.SOUTH&&stack.getCount()==1,"Actual source adjacent placement/facing/cost");h.succeed();}
    @GameTest public void shiftPlacementUsesPlayerDirectionInsteadOfInheritingTheNeighbor(GameTestHelper h){board(h);var user=user(h,new ItemStack(AllBlocks.DISPLAY_BOARD));user.setShiftKeyDown(true);user.setYRot(90);var support=h.absolutePos(P);var context=new BlockPlaceContext(new UseOnContext(user,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(.5,0,0),Direction.EAST,support,false)));h.assertValueEqual(AllBlocks.DISPLAY_BOARD.getStateForPlacement(context).getValue(FlapDisplayBlock.HORIZONTAL_FACING),context.getHorizontalDirection().getOpposite(),"Source sneak placement does not inherit neighbor direction");h.succeed();}
    @GameTest public void actualNearestEdgePlacementHelperCreatesANativeBoardWithRealDebit(GameTestHelper h){board(h);var stack=new ItemStack(AllBlocks.DISPLAY_BOARD,2);var user=user(h,stack);var pos=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(pos).add(0,.5,0),Direction.UP,pos,false);h.assertTrue(h.getBlockState(P).useItemOn(stack,h.getLevel(),user,InteractionHand.MAIN_HAND,hit).consumesAction()&&h.getBlockState(P.above()).is(AllBlocks.DISPLAY_BOARD)&&stack.getCount()==1,"Nearest allowed source edge uses actual BlockItem.place rather than state injection");h.succeed();}
    @GameTest(maxTicks=35)public void actualRectangleFormsOneControllerAndSourceTwoLinesPerBlockHeight(GameTestHelper h){rectangle(h,2,2);h.runAfterDelay(12,()->{var board=be(h,P);h.assertTrue(board.isController&&board.xSize==2&&board.ySize==2&&board.getLines().size()==4&&board.getMaxCharCount()==8,"Actual2x2 rectangle controller dimensions/capacity");h.assertTrue(h.getBlockState(P).getValue(FlapDisplayBlock.DOWN)&&h.getBlockState(P.below()).getValue(FlapDisplayBlock.UP),"Real matching row connections");h.succeed();});}
    @GameTest(maxTicks=35)public void everyActualRectanglePartResolvesTheSameRealTopLeftController(GameTestHelper h){rectangle(h,3,2);h.runAfterDelay(12,()->{var controller=be(h,P);for(int y=0;y<2;y++)for(int x=0;x<3;x++)h.assertTrue(be(h,P.east(x).below(y)).getController()==controller,"Real controller traversal at "+x+","+y);h.succeed();});}
    @GameTest(maxTicks=35)public void differentRowWidthsCannotPretendToBeOneRectangle(GameTestHelper h){rectangle(h,2,1);h.setBlock(P.below(),state());h.runAfterDelay(12,()->{h.assertFalse(h.getBlockState(P).getValue(FlapDisplayBlock.DOWN),"Wider source row refuses vertical merge with shorter row");h.assertTrue(be(h,P).ySize==1&&be(h,P.below()).isController,"Actual lower row remains independent");h.succeed();});}
    @GameTest(maxTicks=35)public void actualDifferentFacingNeighborDoesNotExtendControllerWidth(GameTestHelper h){board(h);h.setBlock(P.east(),state().setValue(FlapDisplayBlock.HORIZONTAL_FACING,Direction.NORTH));h.runAfterDelay(12,()->{h.assertTrue(be(h,P).xSize==1&&!FlapDisplayBlock.canConnect(state(),h.getBlockState(P.east())),"Source facing compatibility is real, not any-board adjacency");h.succeed();});}
    @GameTest(maxTicks=45)public void realCogMotorPathSuppliesRotationAndSourceDisconnectStopsTheBoard(GameTestHelper h){power(h,64);h.runAfterDelay(8,()->{h.assertTrue(Math.abs(be(h,P).getSpeed())==64&&be(h,P).isSpeedRequirementFulfilled()&&be(h,P).getGeneratingSource().equals(h.absolutePos(P.west().north())),"Actual cog mesh and real motor provenance");h.setBlock(P.west(),Blocks.AIR);});h.runAfterDelay(18,()->{h.assertTrue(be(h,P).getSpeed()==0&&!be(h,P).isSpeedRequirementFulfilled(),"Real broken cog path stops the display without synthetic network state");h.succeed();});}
    @GameTest(maxTicks=35)public void actualInsufficientSpeedRejectsNameTagWhileDyeStillWorks(GameTestHelper h){power(h,16);h.runAfterDelay(8,()->{var name=user(h,tag("Too slow"));h.assertFalse(use(h,name,0).consumesAction(),"Source MEDIUM default30RPM is enforced");h.assertTrue(text(h,0).isEmpty(),"Insufficient speed cannot mutate text");var dye=new ItemStack(Items.DYE.pick(DyeColor.BLUE),2);h.assertTrue(use(h,user(h,dye),0).consumesAction()&&be(h,P).colour[0]==DyeColor.BLUE&&dye.getCount()==2,"Source dye interaction remains available at low/stopped speed");h.succeed();});}
    @GameTest(maxTicks=35)public void actualNameTagSetsOnlySelectedSourceLineAndRetainsTheItem(GameTestHelper h){power(h,64);h.runAfterDelay(8,()->{var name=user(h,tag("Actual text"));h.assertTrue(use(h,name,1).consumesAction()&&text(h,1).equals("Actual text")&&text(h,0).isEmpty()&&be(h,P).manualLines[1]&&name.getMainHandItem().getCount()==1,"Real source name-tag/line/manual ownership/cost");h.succeed();});}
    @GameTest(maxTicks=35)public void realEmptyHandClearsOnlySelectedLineWithoutErasingOtherLineOrColor(GameTestHelper h){power(h,64);h.runAfterDelay(8,()->{be(h,P).applyTextManually(0,Component.literal("A"));be(h,P).applyTextManually(1,Component.literal("B"));be(h,P).setColour(0,DyeColor.BLUE);be(h,P).setGlowing(0);h.assertTrue(use(h,user(h,ItemStack.EMPTY),0).consumesAction()&&text(h,0).isEmpty()&&!be(h,P).manualLines[0]&&text(h,1).equals("B")&&be(h,P).colour[0]==DyeColor.BLUE&&be(h,P).isLineGlowing(0),"Actual selected text reset preserves source styling and other row");h.succeed();});}
    @GameTest public void actualStoppedBoardAcceptsCostFreeGlowAndWhiteRestoresDefaultPalette(GameTestHelper h){board(h);var ink=new ItemStack(Items.GLOW_INK_SAC,2);h.assertTrue(use(h,user(h,ink),0).consumesAction()&&be(h,P).isLineGlowing(0)&&ink.getCount()==2,"Source glow is real and not consumed");use(h,user(h,new ItemStack(Items.DYE.pick(DyeColor.RED))),0);h.assertTrue(be(h,P).getLineColor(0)==0xFFB13937,"Exact source bright dye palette");use(h,user(h,new ItemStack(Items.DYE.pick(DyeColor.WHITE))),0);h.assertTrue(be(h,P).colour[0]==null&&be(h,P).getLineColor(0)==0xFFD3C6BA,"Source white resets the actual default, rather than bright white");h.succeed();}
    @GameTest public void sectionAppliesSourceRootLocaleUppercaseTruncationPaddingAndAlignment(GameTestHelper h){var left=new FlapDisplaySection(28,"alphabet",false,false);left.setText(Component.literal("abcde"));left.refresh(false);h.assertTrue(left.getRenderedText().equals("ABCD"),"Actual source fixed character capacity/uppercase");var right=new FlapDisplaySection(28,"numeric",false,false).rightAligned();right.setText(Component.literal(" 12 "));right.refresh(false);h.assertTrue(right.getRenderedText().equals("  12"),"Actual source trim and right alignment");h.succeed();}
    @GameTest public void singleFlapRetainsWholeTextAndRealWideGapLayoutProperties(GameTestHelper h){var section=new FlapDisplaySection(27,"arrival_time",true,true).wideFlaps();section.setText(Component.literal("15s"));section.refresh(true);h.assertTrue(section.getRenderedText().equals("15s")&&section.flapCount()==1&&!section.renderCharsIndividually()&&section.isWide()&&section.hasGap(),"Actual source single multi-character flap and size flags");h.succeed();}
    @GameTest public void actualInstantAnimationSettlesChangedFlapsWithoutLosingFinalText(GameTestHelper h){var section=new FlapDisplaySection(28,"alphabet",false,false);section.setText(Component.literal("ABCD"));section.refresh(true);h.assertTrue(section.isSpinning(0),"Actual changed flap transition starts");section.tick(true,RandomSource.create(1));section.tick(true,RandomSource.create(1));for(int i=0;i<4;i++)h.assertFalse(section.isSpinning(i),"Source >128RPM instant rule settles actual flap "+i);h.assertValueEqual(section.getRenderedText(),"ABCD","Final actual text remains");h.succeed();}
    @GameTest public void legacySectionLayoutKeysRoundtripAndSameKeyStructuralChangesAreSafe(GameTestHelper h){var source=new FlapDisplayLayout(4);var a=new FlapDisplaySection(14,"numeric",false,true).rightAligned();a.setText(Component.literal("12"),h.getLevel().registryAccess());var b=new FlapDisplaySection(18,"arrival_time",true,false).wideFlaps();b.setText(Component.literal("now"),h.getLevel().registryAccess());source.configure("Timetable",List.of(a,b));var out=output(h);source.write(out);var saved=out.buildResult();h.assertTrue(saved.contains("Key")&&saved.contains("Sections"),"Source layout schema");var copy=new FlapDisplayLayout(4);copy.read(input(h,saved));h.assertTrue(copy.isLayout("Timetable")&&copy.getSections().size()==2&&copy.getSections().getFirst().getRenderedText().equals("12")&&copy.getSections().get(1).getRenderedText().equals("now"),"Actual source layout/section/native component decode");source.configure("Timetable",List.of(a));out=output(h);source.write(out);copy.read(input(h,out.buildResult()));h.assertValueEqual(copy.getSections().size(),1,"Same-key native structural update cannot index stale sections");h.succeed();}
    @GameTest public void actualBoardLegacyLineDataResavesBeforeAWorldExists(GameTestHelper h){board(h);be(h,P).applyTextManually(1,Component.literal("Saved"));be(h,P).setColour(1,DyeColor.BLUE);be(h,P).setGlowing(1);var saved=be(h,P).saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(saved.contains("Display1")&&saved.contains("CustomLine1")&&saved.contains("GlowingLine1")&&saved.getStringOr("Dye1","").equals("BLUE"),"Actual source legacy keys and enum spelling");var copy=(FlapDisplayBlockEntity)BlockEntity.loadStatic(h.absolutePos(P),state(),saved,h.getLevel().registryAccess());h.assertTrue(copy!=null&&copy.getLevel()==null&&copy.manualLines[1]&&copy.glowingLines[1]&&copy.colour[1]==DyeColor.BLUE&&copy.getLines().get(1).getSections().getFirst().getText().getString().equals("Saved"),"Exact native text/line data load before setLevel");var resaved=copy.saveWithFullMetadata(h.getLevel().registryAccess());h.assertTrue(resaved.getCompoundOrEmpty("Display1").equals(saved.getCompoundOrEmpty("Display1")),"No-world serialization retains actual resolved component/layout data");h.succeed();}
    @GameTest public void malformedNativeDimensionsAndComponentsCannotAllocateUnboundedDisplayData(GameTestHelper h){board(h);var saved=be(h,P).saveWithFullMetadata(h.getLevel().registryAccess());saved.putInt("XSize",Integer.MAX_VALUE);saved.putInt("YSize",Integer.MIN_VALUE);var line=new CompoundTag();line.putString("Key","Broken");var sections=new net.minecraft.nbt.ListTag();var section=new CompoundTag();section.putFloat("Width",Float.NaN);section.putString("Text","{bad json");sections.add(section);line.put("Sections",sections);saved.put("Display0",line);var copy=(FlapDisplayBlockEntity)BlockEntity.loadStatic(h.absolutePos(P),state(),saved,h.getLevel().registryAccess());h.assertTrue(copy!=null&&copy.xSize==32&&copy.ySize==1&&copy.getLines().getFirst().getSections().getFirst().flapCount()==0,"Native malformed save handling remains bounded and loadable");h.succeed();}
    @GameTest(maxTicks=35)public void directNativeTargetReportsRealCapacityAndMutatesActualComponentState(GameTestHelper h){power(h,64);h.runAfterDelay(8,()->{var target=new DisplayBoardTarget(h.getLevel(),h.absolutePos(P));var stats=target.stats();h.assertTrue(stats.maxRows()==2&&stats.maxColumns()==4&&stats.bounds().contains(Vec3.atCenterOf(h.absolutePos(P))),"Target stats come from actual controller");var result=target.acceptText(0,List.of(Component.literal("LIVE")));h.assertTrue(result.changedRows()==1&&result.status()==TextDisplayTarget.Status.APPLIED&&text(h,0).equals("LIVE"),"Direct target applied a real row, not a fake publishing result");result=target.acceptText(0,List.of());h.assertTrue(result.status()==TextDisplayTarget.Status.UNCHANGED&&!result.changed()&&text(h,0).equals("LIVE"),"Empty direct input reports unchanged actual data");h.succeed();});}
    @GameTest(maxTicks=35)public void directTargetStopsAtActualManualOrCallerReservedSubsequentRows(GameTestHelper h){power(h,64);h.runAfterDelay(8,()->{be(h,P).applyTextManually(1,Component.literal("Owned"));var target=new DisplayBoardTarget(h.getLevel(),h.absolutePos(P));var result=target.acceptText(0,List.of(Component.literal("A"),Component.literal("B")));h.assertTrue(result.status()==TextDisplayTarget.Status.PARTIAL&&result.changedRows()==1&&text(h,1).equals("Owned"),"Actual manual row blocks subsequent automatic text");be(h,P).applyTextManually(1,null);result=target.acceptFlapText(0,List.of(List.of(Component.literal("C")),List.of(Component.literal("D"))),(board,layout,row)->{},false,row->row==1);h.assertTrue(result.changedRows()==1&&text(h,1).isEmpty(),"Real caller-supplied reservation blocks write without a dummy ownership registry");h.succeed();});}
    @GameTest(maxTicks=35)public void directTargetUsesActualSourceConfiguredSectionsAndSingleLineTailPolicy(GameTestHelper h){power(h,64);h.runAfterDelay(8,()->{be(h,P).applyTextManually(1,Component.literal("Keep"));var target=new DisplayBoardTarget(h.getLevel(),h.absolutePos(P));var result=target.acceptFlapText(0,List.of(List.of(Component.literal("12"),Component.literal("s"))),(board,layout,row)->layout.configure("Actual split",List.of(new FlapDisplaySection(14,"numeric",false,true),new FlapDisplaySection(7,"arrival_time",true,false))),false,row->false);var sections=be(h,P).getLines().getFirst().getSections();h.assertTrue(result.changedRows()==1&&sections.size()==2&&sections.getFirst().getText().getString().equals("12")&&sections.get(1).getText().getString().equals("s")&&text(h,1).equals("Keep"),"Actual configured target sections and preserved single-line tail");h.succeed();});}
    @GameTest public void unavailableStoppedAndEmptyDirectTargetRequestsCannotPretendToPublish(GameTestHelper h){board(h);var target=new DisplayBoardTarget(h.getLevel(),h.absolutePos(P));var result=target.acceptText(0,List.of(Component.literal("No power")));h.assertTrue(result.status()==TextDisplayTarget.Status.NOT_RUNNING&&!result.changed()&&text(h,0).isEmpty(),"Stopped target has no successful fake write");var far=new BlockPos(2600000,80,2600000);var oldColumn=state().setValue(FlapDisplayBlock.UP,true).setValue(FlapDisplayBlock.DOWN,true);h.assertTrue(FlapDisplayBlock.updateColumn(h.getLevel(),far,oldColumn)==oldColumn,"Unknown native column frontier preserves both prior connection bits");target=new DisplayBoardTarget(h.getLevel(),far);h.assertTrue(target.stats()==null&&target.acceptText(0,List.of(Component.literal("No target"))).status()==TextDisplayTarget.Status.UNAVAILABLE&&h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Unavailable target creates no chunk ticket or fictional stats");h.succeed();}
    @GameTest public void realDisplayBoardSuppliesTheSourceVerticalGirderConnectorBranch(GameTestHelper h){var girder=AllBlocks.METAL_GIRDER.defaultBlockState().setValue(GirderBlock.AXIS,Direction.Axis.X);for(var side:new Direction[]{Direction.UP,Direction.DOWN}){h.setBlock(P,girder);h.setBlock(P.relative(side),state());var updated=GirderBlock.updateVerticalProperty(h.getLevel(),h.absolutePos(P),girder,side==Direction.UP?GirderBlock.TOP:GirderBlock.BOTTOM,state(),side);h.assertTrue(updated.getValue(side==Direction.UP?GirderBlock.TOP:GirderBlock.BOTTOM),"Real FlapDisplayBlock source girder branch for "+side);h.setBlock(P.relative(side),Blocks.AIR);}h.succeed();}
    @GameTest public void actualNativeBoardRecipeAndLootUseTheSourceInputsAndYield(GameTestHelper h){var input=CraftingInput.of(3,1,List.of(new ItemStack(AllItems.ANDESITE_ALLOY),new ItemStack(AllItems.ELECTRON_TUBE),new ItemStack(AllItems.ANDESITE_ALLOY)));var output=h.getLevel().getServer().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,input,h.getLevel()).orElseThrow().value().assemble(input);h.assertTrue(output.is(AllBlocks.DISPLAY_BOARD.asItem())&&output.getCount()==2,"Actual source2-output recipe");board(h);var drops=Block.getDrops(h.getBlockState(P),h.getLevel(),h.absolutePos(P),be(h,P));h.assertTrue(drops.size()==1&&drops.getFirst().is(AllBlocks.DISPLAY_BOARD.asItem()),"Actual registered board loot");h.succeed();}
}
